SELECT  FROM sn_item WHERE 
AND bill_no = #{bill}
AND  = #{btype}

  AND seq_pi_no = ''AND NOT seq_pi_no = ''

ORDER BY seq_pi_no, seq_dec LIMIT #{limit} FOR UPDATE SKIP LOCKED

mapper.update:
UPDATE sn_item SET delivery_batch_no = #{batchNo}, updated_at = #{now}
WHERE id IN #{i}
  AND status = 'TO_PUSH' AND delivery_batch_no IS NULL

mapper.select:
SELECT  FROM sn_item
WHERE id IN #{i}
  AND  FOR UPDATE

mapper.update:
UPDATE sn_delivery_batch SET result = 'FAILED', fail_code = #{code}, fail_reason = #{reason}, voidable = #{voidable},
  push_state = 'IDLE', next_retry_at = NULL, updated_at = #{now}
WHERE id = #{id}

UPDATE sn_delivery_batch SET result = 'SUCCESS', confirm_method = #{method}, confirmed_at = #{now},
  accepted_qty = #{accepted}, push_state = 'IDLE', next_retry_at = NULL, updated_at = #{now}
WHERE id = #{id}

UPDATE sn_item SET status = 'PUSHED', mes_holder = #{org}, delivery_mode = #{mode}, push_type = 'NEW',
  delivered_at = #{now}, updated_at = #{now}
WHERE delivery_batch_no = #{batchNo} AND status = 'TO_PUSH'

UPDATE sn_push_task SET state = 'QUEUED', run_after = NULL, updated_at = #{now}
WHERE factory_code = #{org} AND task_key = #{key}
  AND ((state = 'WAITING' AND current_batch = #{batchNo}) OR state = 'STOPPED')

UPDATE sn_delivery_batch SET result = 'VOIDED', push_state = 'IDLE', next_retry_at = NULL, manual_reason = #{reason},
  manual_basis = #{basis}, manual_by = #{by}, manual_at = #{now}, updated_at = #{now}
WHERE id = #{id}

mapper.select:
SELECT d.item_id FROM sn_delivery_item d JOIN sn_delivery_batch b ON b.id = d.batch_id
WHERE d.item_id IN #{i}
  AND b.batch_type = 'TRANSFER_OUT' AND b.result IN ('UNCONFIRMED','FAILED')

mapper.update:
UPDATE sn_push_task SET state = 'QUEUED', run_after = NULL, resend = #{resend}, requeue = 0, message = '',
  started_by = #{by}, started_at = #{now}, updated_at = #{now}
WHERE factory_code = #{org} AND task_key = #{key}

UPDATE sn_delivery_batch SET retry_count = 0, receipt_timeouts = 0, push_state = 'IDLE', next_retry_at = NULL,
  repush_count = repush_count + 1, updated_at = #{now}
WHERE factory_code = #{org}  AND result IN ('UNCONFIRMED','FAILED')

UPDATE sn_push_task SET state = #{state}, run_after = #{runAfter}, lease_until = NULL, current_batch = #{batchNo},
  message = #{message}, requeue = 0, resend = IF(#{state} IN ('DONE','STOPPED'), 0, resend), updated_at = #{now}
WHERE factory_code = #{org} AND task_key = #{key}

UPDATE sn_delivery_batch SET receipt_timeouts = receipt_timeouts + 1, push_state = 'IDLE', next_retry_at = NULL,
  fail_code = 'RECEIPT_TIMEOUT', fail_reason = #{reason}, updated_at = #{now}
WHERE id = #{id}

UPDATE sn_delivery_batch SET push_state = 'EXHAUSTED', next_retry_at = NULL, fail_code = 'RECEIPT_TIMEOUT',
  fail_reason = #{reason}, updated_at = #{now}
WHERE id = #{id}

UPDATE sn_delivery_batch SET result = 'UNCONFIRMED', voidable = 0, push_state = 'WAIT_RECEIPT',
  next_retry_at = #{next}, received_at = #{now}, updated_at = #{now}
WHERE id = #{id}

UPDATE sn_delivery_batch SET retry_count = retry_count + 1, push_state = 'WAIT_RETRY', next_retry_at = #{next},
  fail_code = #{code}, fail_reason = #{reason}, updated_at = #{now}
WHERE id = #{id}

UPDATE sn_delivery_batch SET push_state = 'EXHAUSTED', next_retry_at = NULL, fail_code = #{code},
  fail_reason = #{reason}, updated_at = #{now}
WHERE id = #{id}

mapper.select:
SELECT COUNT(*) FROM sn_item WHERE factory_code = #{org} AND status = 'TO_PUSH' AND suspend IS NULL
  AND delivery_batch_no IS NULL
  AND pi_no NOT IN (SELECT pi_no FROM sn_delivery_batch WHERE factory_code = #{org}
    AND batch_type <> 'TRANSFER_OUT' AND result = 'FAILED' AND pulled_at IS NOT NULL AND id <> #{firstTry})
  AND pi_no = #{pi}
  AND bill_no = #{bill}

SELECT COUNT(*) FROM sn_item WHERE factory_code = #{org} AND status = 'TO_PUSH' AND suspend IS NOT NULL
  AND delivery_batch_no IS NULL
  AND pi_no = #{pi}
  AND bill_no = #{bill}

SELECT pi_no FROM sn_item WHERE factory_code = #{org} AND status = 'TO_PUSH' AND suspend IS NULL
  AND delivery_batch_no IS NULL
  AND pi_no NOT IN (SELECT pi_no FROM sn_delivery_batch WHERE factory_code = #{org}
    AND batch_type <> 'TRANSFER_OUT' AND result = 'FAILED')
  AND bill_no = #{bill}
ORDER BY seq_pi_no, seq_dec LIMIT 1

SELECT  FROM sn_item WHERE factory_code = #{org}

    AND mes_holder = #{org}
    AND status <> 'PENDING_ALLOC'

  AND pi_no = #{pi}
  AND id > #{cursor} ORDER BY id LIMIT #{limit}

mapper.sql:
WHERE 1=1 
AND batch_type <> 'TRANSFER_OUT'
AND pi_no = #{pi}
AND batch_no = #{batchNo}
AND source = #{source}
AND batch_type = #{batchType}
AND result = #{result}
AND transfer_doc_no = #{transferNo}

mapper.select:
SELECT FROM sn_delivery_batch
ORDER BY created_at, id ORDER BY created_at DESC, id DESC
LIMIT #{offset}, #{size}

SELECT d.*, i.status, i.factory_code current_factory, i.rev current_rev, i.attach_no, i.length_text length
FROM sn_delivery_item d LEFT JOIN sn_item i ON i.id = d.item_id WHERE d.batch_id = #{batchId}
ORDER BY d.line_no LIMIT #{offset}, #{size}

SELECT b.factory_code, b.batch_no, b.qty, (SELECT COUNT(*) FROM sn_delivery_item d WHERE d.batch_id = b.id
  AND d.receipt_result IS NOT NULL) n
FROM sn_delivery_batch b WHERE b.result = 'SUCCESS' AND b.confirm_method <> 'MANUAL' AND b.confirmed_at >= #{since}
